    <title>用户登录</title>
    <style>
        /* 全局重置与基础样式 */
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
            font-family: 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
        }

        body {
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
            color: #333;
        }

        /* 登录卡片容器 */
        .login-container {
            background: rgba(255, 255, 255, 0.95);
            padding: 40px;
            border-radius: 16px;
            box-shadow: 0 15px 35px rgba(0, 0, 0, 0.2);
            width: 100%;
            max-width: 400px;
            backdrop-filter: blur(10px);
            transition: transform 0.3s ease;
        }

        .login-container:hover {
            transform: translateY(-5px);
        }

        /* 标题部分 */
        .login-header {
            text-align: center;
            margin-bottom: 30px;
        }

        .login-header h2 {
            font-size: 28px;
            color: #333;
            margin-bottom: 10px;
        }

        .login-header p {
            color: #666;
            font-size: 14px;
        }

        /* 表单组 */
        .form-group {
            position: relative;
            margin-bottom: 20px;
        }

        .form-group label {
            display: block;
            margin-bottom: 8px;
            font-size: 14px;
            color: #555;
            font-weight: 600;
        }

        .input-wrapper {
            position: relative;
        }

        .form-control {
            width: 100%;
            padding: 12px 15px;
            padding-right: 40px; /* 为图标留出空间 */
            border: 2px solid #e1e1e1;
            border-radius: 8px;
            font-size: 16px;
            transition: all 0.3s ease;
            outline: none;
        }

        .form-control:focus {
            border-color: #667eea;
            box-shadow: 0 0 0 3px rgba(102, 126, 234, 0.1);
        }

        /* 密码切换图标 */
        .toggle-password {
            position: absolute;
            right: 15px;
            top: 50%;
            transform: translateY(-50%);
            cursor: pointer;
            color: #999;
            user-select: none;
            background: none;
            border: none;
            padding: 0;
            font-size: 18px;
        }

        .toggle-password:hover {
            color: #667eea;
        }

        .toggle-password:focus {
            outline: 2px solid #667eea;
            outline-offset: 2px;
            border-radius: 4px;
        }

        /* 额外选项：记住我 & 忘记密码 */
        .form-options {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 25px;
            font-size: 14px;
        }

        .remember-me {
            display: flex;
            align-items: center;
            color: #666;
            cursor: pointer;
        }

        .remember-me input {
            margin-right: 8px;
            accent-color: #667eea;
            width: 16px;
            height: 16px;
        }

        .forgot-password {
            color: #667eea;
            text-decoration: none;
            font-weight: 600;
            transition: color 0.2s;
        }

        .forgot-password:hover {
            color: #764ba2;
            text-decoration: underline;
        }

        /* 登录按钮 */
        .btn-login {
            width: 100%;
            padding: 14px;
            background: linear-gradient(to right, #667eea, #764ba2);
            color: white;
            border: none;
            border-radius: 8px;
            font-size: 16px;
            font-weight: 600;
            cursor: pointer;
            transition: transform 0.2s, box-shadow 0.2s;
        }

        .btn-login:hover {
            transform: translateY(-2px);
            box-shadow: 0 5px 15px rgba(118, 75, 162, 0.4);
        }

        .btn-login:active {
            transform: translateY(0);
        }

        .btn-login:focus {
            outline: 2px solid #764ba2;
            outline-offset: 2px;
        }

        .btn-login:disabled {
            opacity: 0.7;
            cursor: not-allowed;
            transform: none;
        }

        /* 底部注册链接 */
        .signup-link {
            text-align: center;
            margin-top: 20px;
            font-size: 14px;
            color: #666;
        }

        .signup-link a {
            color: #667eea;
            text-decoration: none;
            font-weight: 600;
        }

        .signup-link a:hover {
            text-decoration: underline;
        }

        /* 简单的加载动画样式 */
        .btn-loading {
            opacity: 0.8;
            cursor: not-allowed;
            position: relative;
            color: transparent !important;
        }

        .btn-loading::after {
            content: "";
            position: absolute;
            left: 50%;
            top: 50%;
            width: 20px;
            height: 20px;
            border: 2px solid #fff;
            border-radius: 50%;
            border-top-color: transparent;
            animation: spin 0.8s linear infinite;
            transform: translate(-50%, -50%);
        }

        @keyframes spin {
            to { transform: translate(-50%, -50%) rotate(360deg); }
        }

        /* 移动端适配 */
        @media (max-width: 480px) {
            .login-container {
                padding: 30px 20px;
                margin: 20px;
            }
        }
    </style>
</head>
<body>

    <div class="login-container">
        <div class="login-header">
            <h2>欢迎回来</h2>
            <p>请输入您的账号信息以继续</p>
        </div>

        <form id="loginForm">
            <!-- 邮箱/用户名输入 -->
            <div class="form-group">
                <label for="email">邮箱地址</label>
                <div class="input-wrapper">
                    <input type="email" id="email" class="form-control" placeholder="name@example.com" required aria-required="true">
                </div>
            </div>

            <!-- 密码输入 -->
            <div class="form-group">
                <label for="password">密码</label>
                <div class="input-wrapper">
                    <input type="password" id="password" class="form-control" placeholder="请输入密码" required aria-required="true">
                    <button type="button" class="toggle-password" onclick="togglePassword()" aria-label="显示密码">👁️</button>
                </div>
            </div>

            <!-- 选项 -->
            <div class="form-options">
                <label class="remember-me">
                    <input type="checkbox" name="remember"> 记住我
                </label>
                <a href="#" class="forgot-password">忘记密码?</a>
            </div>

            <!-- 提交按钮 -->
            <button type="submit" class="btn-login" id="submitBtn">立即登录</button>
        </form>

        <div class="signup-link">
            还没有账号? <a href="#">立即注册</a>
        </div>
    </div>

    <script>
        // 切换密码显示/隐藏
        function togglePassword() {
            const passwordInput = document.getElementById('password');
            const toggleBtn = document.querySelector('.toggle-password');

            if (passwordInput.type === 'password') {
                passwordInput.type = 'text';
                toggleBtn.textContent = '🙈';
                toggleBtn.setAttribute('aria-label', '隐藏密码');
            } else {
                passwordInput.type = 'password';
                toggleBtn.textContent = '👁️';
                toggleBtn.setAttribute('aria-label', '显示密码');
            }
            passwordInput.focus();
        }

        // 模拟登录提交
        document.getElementById('loginForm').addEventListener('submit', function(e) {
            e.preventDefault(); // 阻止默认表单提交

            const btn = document.getElementById('submitBtn');
            const email = document.getElementById('email').value;

            // 添加加载状态
            btn.classList.add('btn-loading');
            btn.disabled = true;
            btn.textContent = '登录中...';

            // 模拟网络请求延迟
            setTimeout(() => {
                btn.classList.remove('btn-loading');
                btn.disabled = false;
                btn.textContent = '立即登录';
                alert(`登录成功！\n欢迎用户: ${email}`);
                // 在这里可以添加实际的后端 API 调用逻辑
            }, 1500);
        });
    </script>
</body>
</html>", "mode": "overwrite"}}
    ]
}

